setup=constant('validate-war-scouter.py','setup');board=constant('validate-war-board.py','fixture');bundle=(base/'dist/tu-integrated-staging-dev.user.js').read_text();out=base.parent/'development/evidence/war-coordination-115';out.mkdir(parents=True,exist_ok=True)
